window.AUTH=window.AUTH||{};window.AUTH["18-882"]={"d":"18-882","id":"2019/18-882","n":"Babb v. Wilkie","briefs":[{"k":"petitioner","label":"Brief of petitioner Noris Babb","date":"2019-09-17","url":"https://www.supremecourt.gov/DocketPDF/18/18-882/116073/20190917155727583_No.%2018-882%20Babb%20Opening%20Brief%20of%20Petitioner%20with%20addendum.pdf","side":"pet","n":106},{"k":"respondent","label":"Brief of respondent Robert Wilkie, Secretary of Veterans Affairs","date":"2019-11-22","url":"https://www.supremecourt.gov/DocketPDF/18/18-882/123486/20191122182041121_18-882bsUnitedStates.pdf","side":"res","n":91},{"k":"reply","label":"Reply of petitioner Noris Babb","date":"2019-12-23","url":"https://www.supremecourt.gov/DocketPDF/18/18-882/126533/20191223125440257_2019-12-23%20Babb%20Merits%20Reply%20Br.pdf","side":"pet","n":36}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/589US2PP_final.pdf#page=291","tr":true,"items":[{"t":"case","label":"Adarand Constructors, Inc. v. Pena","cite":"515 U.S. 200","y":1995,"id":"1994/93-1841","sc":1,"by":{"0":"26, 32","1":"36","2":"7"}},{"t":"case","label":"Arroyo v. Shinseki, Request No. 0520120563","cite":"2013 WL 393575","y":2013,"court":"E.E.O.C. Jan. 25","by":{"0":"42","1":"50","2":"24"}},{"t":"case","label":"Artis v. District of Columbia","cite":"138 S. Ct. 594","y":2018,"id":"2017/16-460","sc":1,"by":{"0":"21"},"q":[{"src":"brief","b":0,"text":"‘look[s] first to its language, giving the words used their ordinary meaning.’","cite":"138 S. Ct. 594, 603"}]},{"t":"case","label":"Bolling v. Sharpe","cite":"347 U.S. 497","y":1954,"id":"1940-1955/347us497","sc":1,"by":{"0":"5, 34"},"q":[{"src":"argument","who":"Mr. Martinez","text":"They cite Bolling versus Sharpe. Both the legislative history and this Court's decision in Brown and makes clear -- both of them make clear that the purpose of this statute was to -- was to capture the same kind of constitutional equal protection injuries that were at stake in the long line of cases that we've cited in our brief."}]},{"t":"case","label":"Bragdon v. Abbott","cite":"524 U.S. 624","y":1998,"id":"1997/97-156","sc":1,"by":{"0":"38","1":"43"},"q":[{"src":"brief","b":0,"text":"Congress’ repetition of a well-established term carries the implication that Congress intended the term to be construed in accordance with pre-existing regulatory interpretations.","cite":"524 U.S. 624, 631"},{"src":"brief","b":1,"text":"‘Congress’ repetition of a well-established term carries the implication that Congress intended that term to be construed in accordance with pre-existing regulatory interpretations.’","cite":"524 U.S. 624, 631"}]},{"t":"case","label":"Brenton W. v. Chao, Appeal No. 0120130554","cite":"2017 WL 2953878","y":2017,"court":"E.E.O.C. June 29","by":{"0":"11, 41, 42, 47","1":"49"},"q":[{"src":"argument","who":"Mr. Martinez","text":"If you look at the Brenton case that we cite at pages 41 to 42 of our brief, that case involved a -- a written memorandum. The policy said that someone's ability to control traffic declines with age, and they were treating applicants for those positions badly for that reason."}]},{"t":"case","label":"Brown v. General Services Administration","cite":"425 U.S. 820","y":1976,"id":"1975/74-768","sc":1,"by":{"0":"5, 6, 8, 31, 58","1":"39","2":"9"},"q":[{"src":"brief","b":0,"text":"the effective availability of either administrative or judicial relief was far from sure.","cite":"425 U.S. at 825"},{"src":"brief","b":0,"text":"seeking to enjoin unconstitutional agency conduct [based on race],","cite":"425 U.S. at 826"},{"src":"brief","b":1,"text":"the effective availability of either administrative or judicial relief [for federal employees] was far from sure.","cite":"425 U.S. 820, 825"}]},{"t":"case","label":"Burlington Northern & Santa Fe Railway Co. v. White","cite":"548 U.S. 53","y":2006,"id":"2005/05-259","sc":1,"by":{"0":"25"}},{"t":"case","label":"Chanelle B. v. Brennan, Appeal No. 0120152401","cite":"2017 WL 6422255","y":2017,"court":"E.E.O.C. Dec. 8","by":{"0":"42","1":"50"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. Natural Resources Defense Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"by":{"0":"2","1":"45"},"q":[{"src":"argument","who":"General Francisco","text":"Now, I think that my friend may get up on rebuttal and point to Chevron and so I would like to take one moment to address the Chevron issue in -- in advance."}]},{"t":"case","label":"Clements v. Fashing","cite":"457 U.S. 957","y":1982,"id":"1981/80-1290","sc":1,"by":{"0":"32","1":"35"}},{"t":"case","label":"FDIC v. Philadelphia Gear Corp.","cite":"476 U.S. 426","y":1986,"id":"1985/84-1972","sc":1,"by":{"0":"38","1":"43"}},{"t":"case","label":"Federal Express Corp. v. Holowecki","cite":"552 U.S. 389","y":2008,"id":"2007/06-1322","sc":1,"by":{"0":"41"}},{"t":"case","label":"Food Marketing Institute v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"by":{"0":"21"}},{"t":"case","label":"Ford v. Mabus","cite":"629 F.3d 198","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/629/198/","by":{"0":"passim","1":"31, 51, 52","2":"4, 24"},"q":[{"src":"brief","b":0,"text":"any amount of discrimination tainting a personnel action","cite":"629 F.3d at 206"},{"src":"brief","b":0,"text":"divorce[s] the phrase ‘free from any discrimination’ from its plain meaning.","cite":"629 F.3d at 206"}]},{"t":"case","label":"Forman v. Small","cite":"271 F.3d 285","y":2001,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/271/285/","by":{"0":"23, 52"}},{"t":"case","label":"Gomez-Perez v. Potter","cite":"553 U.S. 474","y":2008,"id":"2007/06-1321","sc":1,"by":{"0":"20, 50, 51, 52","1":"6, 21, 26, 35, 42, 49","2":"15, 17, 18"},"q":[{"src":"brief","b":0,"text":"the prohibitory language in the ADEA’s federal-sector provision differs sharply from that in the corresponding ADEA provision relating to privatesector employment.","cite":"553 U.S. 474, 486"},{"src":"brief","b":0,"text":"specific list of forbidden [age-based] employer practices.","cite":"553 U.S. at 488, 486-87"},{"src":"brief","b":1,"text":"does not incorporate [Title VII’s] provision prohibiting retaliation in the private sector,","cite":"553 U.S. 474, 487-488"},{"src":"brief","b":1,"text":"[m]ore serious personnel actions, known as ‘adverse actions,’","cite":"553 U.S. at 501"}]},{"t":"case","label":"Gratz v. Bollinger","cite":"539 U.S. 244","y":2003,"id":"2002/02-516","sc":1,"by":{"0":"26, 32","1":"35"}},{"t":"case","label":"Gross v. FBL Financial Services, Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"by":{"0":"20, 50, 51, 57","1":"passim","2":"9, 16, 18"},"q":[{"src":"brief","b":0,"text":"require[s] that an employer took adverse action ‘because of’ age.","cite":"557 U.S. at 176"},{"src":"brief","b":1,"text":"prov[es] by a preponderance of the evidence that it would have made the same decision even if [the employer] had not taken that factor into account.","cite":"557 U.S. 167, 173-174"},{"src":"brief","b":1,"text":"have no bearing on the correct interpretation of ADEA claims,","cite":"557 U.S. at 180 n.6"},{"src":"brief","b":2,"text":"that an employer took adverse action ‘because of’ age.","cite":"557 U.S. at 176"},{"src":"argument","who":"Mr. Martinez","text":"Congress chose those words carefully rejecting the private sector language later addressed in Gross and Nassar. It did so in the unique federal sector context to create a remedy for violating constitutional equal protection rights."},{"src":"argument","who":"Justice Kavanaugh","text":"And that's a term that's used in Nassar, a term that used in Gross, the word \"action,\" and the action is usually referred to as an adverse employment action, namely as Justice Kagan says, the decision."},{"src":"argument","who":"Justice Gorsuch","text":"-- which, of course, we can't do because of Gross, and point specifically to the language saying, you know, you can't discriminate in hiring or otherwise, right, discriminate --"}]},{"t":"case","label":"Henry v. McHugh, Appeal No. 0120103221","cite":"2010 WL 5551957","y":2010,"court":"E.E.O.C. Dec. 23","by":{"0":"42","1":"50"}},{"t":"case","label":"Jackson v. Birmingham Board of Education","cite":"544 U.S. 167","y":2005,"id":"2004/02-1672","sc":1,"by":{"0":"25","1":"12, 17","2":"4"},"q":[{"src":"brief","b":0,"text":"‘Discrimination’ is a term that covers a wide range of intentional unequal treatment; by using such a broad term, Congress gave the statute a broad reach.","cite":"544 U.S. 167, 175"},{"src":"brief","b":0,"text":"differential treatment, or more specifically, less favorable treatment.","cite":"544 U.S. at 174"}]},{"t":"case","label":"Lehman v. Nakshian","cite":"453 U.S. 156","y":1981,"id":"1980/80-242","sc":1,"by":{"0":"passim","1":"37, 43","2":"20"},"q":[{"src":"brief","b":0,"text":"was patterned ‘directly after’ Title VII’s federal sector discrimination ban.","cite":"453 U.S. at 167 n.15"},{"src":"brief","b":0,"text":"ADEA coverage of federal employees was to be accomplished by the addition of an entirely new and separate section to the Act [i.e., Section 633a].","cite":"453 U.S. at 166 n.14"},{"src":"brief","b":2,"text":"Congress deliberately prescribed a distinct statutory scheme applicable only to the federal sector,","cite":"453 U.S. 156, 166-67"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"applied only to actions against private employers.","cite":"453 U. S. 156, 166"}]},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"by":{"0":"38","1":"43"}},{"t":"case","label":"McDonnell Douglas Corp. v. Green","cite":"411 U.S. 792","y":1973,"id":"1972/72-490","sc":1,"by":{"0":"16","1":"10"}},{"t":"case","label":"McQuiggin v. Perkins","cite":"569 U.S. 383","y":2013,"id":"2012/12-126","sc":1,"by":{"0":"29"},"q":[{"src":"brief","b":0,"text":"Congress legislates against the backdrop of existing law.","cite":"569 U.S. 383, 398 n.3"}]},{"t":"case","label":"Mississippi ex rel. Hood v. AU Optronics Corp.","cite":"571 U.S. 161","y":2014,"id":"2013/12-1036","sc":1,"by":{"0":"29"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"by":{"0":"8, 33, 36","1":"39","2":"12"},"q":[{"src":"brief","b":0,"text":"in large part merely a codification of","cite":"417 U.S. at 549"}]},{"t":"case","label":"Mt. Healthy City School District Board of Education v. Doyle","cite":"429 U.S. 274","y":1977,"id":"1976/75-1278","sc":1,"by":{"0":"32","1":"28, 48, 52"},"q":[{"src":"brief","b":1,"text":"distinguishe[d] between a result caused by a constitutional violation and one not so caused.","cite":"429 U.S. at 286"}]},{"t":"case","label":"Northcross v. Board of Education of Memphis City Schools","cite":"412 U.S. 427","y":1973,"id":"1972/72-1164","sc":1,"by":{"0":"30"}},{"t":"case","label":"Northeastern Florida Chapter of Associated General Contractors of America v. City of Jacksonville","cite":"508 U.S. 656","y":1993,"id":"1992/91-1721","sc":1,"by":{"0":"passim","1":"27, 35","2":"4"},"q":[{"src":"brief","b":0,"text":"erect[ing] a barrier that makes it more difficult for members of one group to obtain a benefit than it is for members of another group.","cite":"508 U.S. at 664"},{"src":"brief","b":0,"text":"[t]he relevant injury in such cases is ‘the inability to compete on an equal footing’","cite":"508 U.S. at 666"},{"src":"brief","b":2,"text":"that makes it more difficult for members of one group to obtain [the] benefit than it is for members of another.","cite":"508 U.S. 656, 666"}]},{"t":"case","label":"Parents Involved in Community Schools v. Seattle School District No. 1","cite":"551 U.S. 701","y":2007,"id":"2006/05-915","sc":1,"by":{"0":"26, 32","1":"27, 35","2":"7"},"q":[{"src":"argument","who":"Mr. Martinez","text":"What we've argued is that the injury at stake in this case is the same kind of process-based equal protection type injury that this Court has repeatedly identified in cases from Bakke up through Parents Involved."}]},{"t":"case","label":"Price Waterhouse v. Hopkins","cite":"490 U.S. 228","y":1989,"id":"1988/87-1167","sc":1,"by":{"0":"56, 57","1":"passim","2":"20, 22"},"q":[{"src":"brief","b":1,"text":"Congress clearly conditioned legal liability on a determination that the consideration of an illegitimate factor caused a tangible employment injury of some kind.","cite":"490 U.S. at 265"},{"src":"brief","b":2,"text":"pinpoint discrimination as the precise cause of [their] injury, despite having shown that it played a significant role in the decisional process.","cite":"490 U.S. at 273"},{"src":"argument","who":"Justice Kavanaugh","text":"The Price Waterhouse-type standard that Justice Breyer brought up."},{"src":"argument","who":"Mr. Martinez","text":"I think Justice Breyer was talking about what Congress did to fix the problem of Price Waterhouse. So Price Waterhouse happens. Congress decides that the Price Waterhouse test is insufficiently protective of victims."},{"src":"argument","who":"General Francisco","text":"With all respect I find that simply implausible, given that it took us Price Waterhouse, Congress's reaction to that, and a whole bunch of other decisions in order to come up with the motivating factor test."}]},{"t":"case","label":"Regents of the University of California v. Bakke","cite":"438 U.S. 265","y":1978,"id":"1979/76-811","sc":1,"by":{"0":"26, 27, 32","1":"35","2":"9, 11"},"q":[{"src":"brief","b":0,"text":"even if [he was] unable to prove that he would have been admitted [to UCLA’s law school] in the absence of the [challenged affirmative-action] program.","cite":"438 U.S. at 280 n.14"}]},{"t":"case","label":"Roberts v. Sea-Land Services, Inc.","cite":"566 U.S. 93","y":2012,"id":"2011/10-1399","sc":1,"by":{"0":"44"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"by":{"0":"21"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"by":{"0":"29"},"q":[{"src":"brief","b":0,"text":"is obviously transplanted from another legal source, whether the common law or other legislation, it brings the old soil with it.","cite":"570 U.S. 729, 733"}]},{"t":"case","label":"Smith v. City of Jackson","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"differential treatment, or more specifically, less favorable treatment.","cite":"544 U.S. at 174"},{"src":"brief","b":0,"text":"when Congress uses the same language in two statutes having similar purposes, particularly when one is enacted shortly after the other, it is appropriate to presume that Congress intended that text to have the same meaning in both statutes.","cite":"544 U.S. 228, 233"}]},{"t":"case","label":"Texas v. Lesage","cite":"528 U.S. 18","y":1999,"id":"1999/98-1111","sc":1,"by":{"0":"26, 32, 58","1":"27, 28, 35, 53","2":"10, 11"}},{"t":"case","label":"Trask v. Secretary, Department of Veterans Affairs","cite":"822 F.3d 1179","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/822/1179/","by":{"0":"17, 43"}},{"t":"case","label":"Trinity Lutheran Church of Columbia, Inc. v. Comer","cite":"137 S. Ct. 2012","y":2017,"id":"2016/15-577","sc":1,"by":{"0":"32","1":"35"}},{"t":"case","label":"Turner v. Fouche","cite":"396 U.S. 346","y":1970,"id":"1969/23","sc":1,"by":{"0":"26, 32","1":"35"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"by":{"0":"30"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"by":{"0":"24"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"by":{"0":"41"}},{"t":"case","label":"University of Texas Southwest Medical Center v. Nassar","cite":"570 U.S. 338","y":2013,"id":"2012/12-484","sc":1,"by":{"0":"45, 46","1":"passim","2":"15, 20"},"q":[{"src":"brief","b":0,"text":"an indication to the contrary in the statute.","cite":"570 U.S. at 347"},{"src":"brief","b":1,"text":"show[ing] that a discriminatory motive was not [a] but-for cause of the adverse employment action.","cite":"570 U.S. 338, 348"},{"src":"brief","b":1,"text":"‘harm would not have occurred’ in the absence of—that is, but for—the defendant’s conduct.","cite":"570 U.S. 338, 346-347"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"[c]ausation in fact—i. e., proof that the defendant's conduct did in fact cause the plaintiff 's injury—is a standard requirement of any tort claim,","cite":"570 U. S. 338, 346"}]},{"t":"usc","label":"2 U.S.C. § 1311","url":"https://www.law.cornell.edu/uscode/text/2/1311","by":{"0":"52"}},{"t":"usc","label":"3 U.S.C. § 411","url":"https://www.law.cornell.edu/uscode/text/3/411","subs":["(a)"],"by":{"0":"52"}},{"t":"usc","label":"5 U.S.C. § 7151","url":"https://www.law.cornell.edu/uscode/text/5/7151","by":{"0":"33"},"q":[{"src":"brief","b":0,"text":"the policy of the United States to insure equal employment opportunities for Federal employees without discrimination because of race, color, religion, sex, or national origin.","cite":"5 U.S.C. § 7151"}]},{"t":"usc","label":"5 U.S.C. § 7201","url":"https://www.law.cornell.edu/uscode/text/5/7201","subs":["(b)"],"by":{"0":"7, 47"}},{"t":"usc","label":"22 U.S.C. § 1626","url":"https://www.law.cornell.edu/uscode/text/22/1626","subs":["(a)"],"by":{"0":"22"}},{"t":"usc","label":"26 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/26/401","subs":["(a)(27)(A)"],"by":{"0":"22"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 623","url":"https://www.law.cornell.edu/uscode/text/29/623","subs":["(a)","(a)(1)","(d)"],"stext":{"head":"§623. Prohibition of age discrimination","paras":[[0,"(a) Employer practices"],[0,"It shall be unlawful for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual or otherwise discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's age;"],[1,"(2) to limit, segregate, or classify his employees in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's age; or"],[1,"(3) to reduce the wage rate of any employee in order to comply with this chapter."],[0,"(b) Employment agency practices"],[0,"It shall be unlawful for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of such individual's age, or to classify or refer for employment any individual on the basis of such individual's age."],[0,"(c) Labor organization practices"],[0,"It shall be unlawful for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his age;"],[1,"(2) to limit, segregate, or classify its membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's age;"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Opposition to unlawful practices; participation in investigations, proceedings, or litigation"],[0,"It shall be unlawful for an employer to discriminate against any of his employees or applicants for employment, for an employment agency to discriminate against any individual, or for a labor organization to discriminate against any member thereof or applicant for membership, because such individual, member or applicant for membership has opposed any practice made unlawful by this section, or because such individual, member or applicant for membership has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or litigation under this chapter."],[0,"(e) Printing or publication of notice or advertisement indicating preference, limitation, etc."],[0,"It shall be unlawful for an employer, labor organization, or employment agency to print or publish, or cause to be printed or published, any notice or advertisement relating to employment by such an employer or membership in or any classification or referral for employment by such a labor organization, or relating to any classification or referral for employment by such an employment agency, indicating any preference, limitation, specification, or discrimination, based on age."],[0,"(f) Lawful practices; age an occupational qualification; other reasonable factors; laws of foreign workplace; seniority system; employee benefit plans; discharge or discipline for good cause"],[0,"It shall not be unlawful for an employer, employment agency, or labor organization—"],[1,"(1) to take any action otherwise prohibited under subsections (a), (b), (c), or (e) of this section where age is a bona fide occupational qualification reasonably necessary to the normal operation of the particular business, or where the differentiation is based on reasonable factors other than age, or where such practices involve an employee in a workplace in a foreign country, and compliance with such subsections would cause such employer, or a corporation controlled by such employer, to violate the laws of the country in which such workplace is located;"],[1,"(2) to take any action otherwise prohibited under subsection (a), (b), (c), or (e) of this section—"],[2,"(A) to observe the terms of a bona fide seniority system that is not intended to evade the purposes of this chapter, except that no such seniority system shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title because of the age of such individual; or"],[2,"(B) to observe the terms of a bona fide employee benefit plan—"],[3,"(i) where, for each benefit or benefit package, the actual amount of payment made or cost incurred on behalf of an older worker is no less than that made or incurred on behalf of a younger worker, as permissible under section 1625.10, title 29, Code of Federal Regulations (as in effect on June 22, 1989); or"],[3,"(ii) that is a voluntary early retirement incentive plan consistent with the relevant purpose or purposes of this chapter."],[1,"Notwithstanding clause (i) or (ii) of subparagraph (B), no such employee benefit plan or voluntary early retirement incentive plan shall excuse the failure to hire any individual, and no such employee benefit plan shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title, because of the age of such individual. An employer, employment agency, or labor organization acting under subparagraph (A), or under clause (i) or (ii) of subparagraph (B), shall have the burden of proving that such actions are lawful in any civil enforcement proceeding brought under this chapter; or"],[1,"(3) to discharge or otherwise discipline an individual for good cause."],[0,"(g) Repealed. Pub. L. 101–239, title VI, §6202(b)(3)(C)(i), Dec. 19, 1989, 103 Stat. 2233"],[0,"(h) Practices of foreign corporations controlled by American employers; foreign employers not controlled by American employers; factors determining control"],[0,"(1) If an employer controls a corporation whose place of incorporation is in a foreign country, any practice by such corporation prohibited under this section shall be presumed to be such practice by such employer."],[0,"(2) The prohibitions of this section shall not apply where the employer is a foreign person not controlled by an American employer."],[0,"(3) For the purpose of this subsection the determination of whether an employer controls a corporation shall be based upon the—"],[1,"(A) interrelation of operations,"],[1,"(B) common management,"],[1,"(C) centralized control of labor relations, and"],[1,"(D) common ownership or financial control,"],[0,"of the employer and the corporation."],[0,"(i) Employee pension benefit plans; cessation or reduction of benefit accrual or of allocation to employee account; distribution of benefits after attainment of normal retirement age; compliance; highly compensated employees"],[0,"(1) Except as otherwise provided in this subsection, it shall be unlawful for an employer, an employment agency, a labor organization, or any combination thereof to establish or maintain an employee pension benefit plan which requires or permits—"],[1,"(A) in the case of a defined benefit plan, the cessation of an employee's benefit accrual, or the reduction of the rate of an employee's benefit accrual, because of age, or"],[1,"(B) in the case of a defined contribution plan, the cessation of allocations to an employee's account, or the reduction of the rate at which amounts are allocated to an employee's account, because of age."],[0,"(2) Nothing in this section shall be construed to prohibit an employer, employment agency, or labor organization from observing any provision of an employee pension benefit plan to the extent that such provision imposes (without regard to age) a limitation on the amount of benefits that the plan provides or a limitation on the number of years of service or years of participation which are taken into account for purposes of determining benefit accrual under the plan."],[0,"(3) In the case of any employee who, as of the end of any plan year under a defined benefit plan, has attained normal retirement age under such plan—"],[1,"(A) if distribution of benefits under such plan with respect to such employee has commenced as of the end of such plan year, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of the actuarial equivalent of in-service distribution of benefits, and"],[1,"(B) if distribution of benefits under such plan with respect to such employee has not commenced as of the end of such year in accordance with section 1056(a)(3) of this title and section 401(a)(14)(C) of title 26, and the payment of benefits under such plan with respect to such employee is not suspended during such plan year pursuant to section 1053(a)(3)(B) of this title or section 411(a)(3)(B) of title 26, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of any adjustment in the benefit payable under the plan during such plan year attributable to the delay in the distribution of benefits after the attainment of normal retirement age."],[0,"The provisions of this paragraph shall apply in accordance with regulations of the Secretary of the Treasury. Such regulations shall provide for the application of the preceding provisions of this paragraph to all employee pension benefit plans subject to this subsection and may provide for the application of such provisions, in the case of any such employee, with respect to any period of time within a plan year."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/623?type=usc&year=mostrecent&link-type=html"},"by":{"0":"50, 7, 51","1":"37, 37, 37","2":"16, 17"},"q":[{"src":"brief","b":0,"text":"[i]t shall be unlawful for an employer . . . to fail or refuse to hire or to discharge any individual or otherwise discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual’s age.","cite":"29 U.S.C. § 623(a)(1)"},{"src":"brief","b":0,"text":"fail or refuse to hire or to discharge any individual, or otherwise discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual’s age.","cite":"29 U.S.C. § 623(a)(1)"},{"src":"brief","b":1,"text":"age was [a] ‘but-for’ cause of the employer’s adverse action.","cite":"29 U.S.C. 623(a)(1)"},{"src":"brief","b":1,"text":"because such individual * * * has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or litigation under th[e ADEA].","cite":"29 U.S.C. 623(d)"},{"src":"brief","b":2,"text":"otherwise discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual’s age.","cite":"29 U.S.C. § 623(a)(1)"}]},{"t":"usc","label":"29 U.S.C. § 633a","url":"https://www.law.cornell.edu/uscode/text/29/633a","subs":["(a)","(b)","(c)","(f)"],"stext":{"head":"§633a. Nondiscrimination on account of age in Federal Government employment","paras":[[0,"(a) Federal agencies affected"],[0,"All personnel actions affecting employees or applicants for employment who are at least 40 years of age (except personnel actions with regard to aliens employed outside the limits of the United States) in military departments as defined in section 102 of title 5, in executive agencies as defined in section 105 of title 5 (including employees and applicants for employment who are paid from nonappropriated funds), in the United States Postal Service and the Postal Regulatory Commission, in those units in the government of the District of Columbia having positions in the competitive service, and in those units of the judicial branch of the Federal Government having positions in the competitive service, in the Smithsonian Institution, and in the Government Publishing Office, the Government Accountability Office, and the Library of Congress shall be made free from any discrimination based on age."],[0,"(b) Enforcement by Equal Employment Opportunity Commission and by Librarian of Congress in the Library of Congress; remedies; rules, regulations, orders, and instructions of Commission: compliance by Federal agencies; powers and duties of Commission; notification of final action on complaint of discrimination; exemptions: bona fide occupational qualification"],[0,"Except as otherwise provided in this subsection, the Equal Employment Opportunity Commission is authorized to enforce the provisions of subsection (a) through appropriate remedies, including reinstatement or hiring of employees with or without backpay, as will effectuate the policies of this section. The Equal Employment Opportunity Commission shall issue such rules, regulations, orders, and instructions as it deems necessary and appropriate to carry out its responsibilities under this section. The Equal Employment Opportunity Commission shall—"],[1,"(1) be responsible for the review and evaluation of the operation of all agency programs designed to carry out the policy of this section, periodically obtaining and publishing (on at least a semiannual basis) progress reports from each department, agency, or unit referred to in subsection (a);"],[1,"(2) consult with and solicit the recommendations of interested individuals, groups, and organizations relating to nondiscrimination in employment on account of age; and"],[1,"(3) provide for the acceptance and processing of complaints of discrimination in Federal employment on account of age."],[0,"The head of each such department, agency, or unit shall comply with such rules, regulations, orders, and instructions of the Equal Employment Opportunity Commission which shall include a provision that an employee or applicant for employment shall be notified of any final action taken on any complaint of discrimination filed by him thereunder. Reasonable exemptions to the provisions of this section may be established by the Commission but only when the Commission has established a maximum age requirement on the basis of a determination that age is a bona fide occupational qualification necessary to the performance of the duties of the position. With respect to employment in the Library of Congress, authorities granted in this subsection to the Equal Employment Opportunity Commission shall be exercised by the Librarian of Congress."],[0,"(c) Civil actions; jurisdiction; relief"],[0,"Any person aggrieved may bring a civil action in any Federal district court of competent jurisdiction for such legal or equitable relief as will effectuate the purposes of this chapter."],[0,"(d) Notice to Commission; time of notice; Commission notification of prospective defendants; Commission elimination of unlawful practices"],[0,"When the individual has not filed a complaint concerning age discrimination with the Commission, no civil action may be commenced by any individual under this section until the individual has given the Commission not less than thirty days' notice of an intent to file such action. Such notice shall be filed within one hundred and eighty days after the alleged unlawful practice occurred. Upon receiving a notice of intent to sue, the Commission shall promptly notify all persons named therein as prospective defendants in the action and take any appropriate action to assure the elimination of any unlawful practice."],[0,"(e) Duty of Government agency or official"],[0,"Nothing contained in this section shall relieve any Government agency or official of the responsibility to assure nondiscrimination on account of age in employment as required under any provision of Federal law."],[0,"(f) Applicability of statutory provisions to personnel action of Federal departments, etc."],[0,"Any personnel action of any department, agency, or other entity referred to in subsection (a) of this section shall not be subject to, or affected by, any provision of this chapter, other than the provisions of sections 626(d)(3) and 631(b) of this title and the provisions of this section."],[0,"(g) Study and report to President and Congress by Equal Employment Opportunity Commission; scope"],[0,"(1) The Equal Employment Opportunity Commission shall undertake a study relating to the effects of the amendments made to this section by the Age Discrimination in Employment Act Amendments of 1978, and the effects of section 631(b) of this title."],[0,"(2) The Equal Employment Opportunity Commission shall transmit a report to the President and to the Congress containing the findings of the Commission resulting from the study of the Commission under paragraph (1) of this subsection. Such report shall be transmitted no later than January 1, 1980."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/633a?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4, passim, 10, 41, 10, 47, 50","1":"passim, passim, passim","2":"1, 3, 5"},"q":[{"src":"brief","b":0,"text":"[a]ll personnel actions affecting employees or applicants for employment who are at least 40 years of age . . . shall be made free from any discrimination based on age.","cite":"29 U.S.C. § 633a(a)"},{"src":"brief","b":0,"text":"[a]ll personnel actions . . . shall be made free from any discrimination based on age.","cite":"29 U.S.C. § 633a(a)"},{"src":"brief","b":1,"text":"who are at least 40 years of age * * * shall be made free from any discrimination based on age.","cite":"29 U.S.C. 633a(a)"},{"src":"brief","b":1,"text":"shall be made free from any discrimination based on age,","cite":"29 U.S.C. 633a(a)"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"All personnel actions affecting employees or applicants for employment who are at least 40 years of age . . . shall be made free from any discrimination based on age.","cite":"29 U. S. C. § 633a(a)"},{"src":"argument","who":"Mr. Martinez","text":"Chief Justice, and may it please the Court: Section 633a states that all federal personnel actions shall be made free from any discrimination based on age."},{"src":"argument","who":"General Francisco","text":"That's why Senator Bentsen, Section 633a's principal sponsor, said that under 633a, \"government employees will be subject to the same protections against arbitrary employment based on age as are employees in the private sector.\" Now, we've had some discussion about the Civil Service Reform Act, and I actually think it's very instructive here to the interpretive question."},{"src":"argument","who":"General Francisco","text":"I think that's basically right because the things that he is concerned about, the types of policies that he's concerned about, couldn't happen within the Federal Government because of a whole host of laws, wholly apart from Section 633a."}]},{"t":"usc","label":"29 U.S.C. § 791","url":"https://www.law.cornell.edu/uscode/text/29/791","subs":["(f)"],"by":{"0":"53"}},{"t":"usc","label":"29 U.S.C. § 2611","url":"https://www.law.cornell.edu/uscode/text/29/2611","subs":["(4)"],"by":{"0":"53"}},{"t":"usc","label":"38 U.S.C. § 4303","url":"https://www.law.cornell.edu/uscode/text/38/4303","subs":["(4)"],"by":{"0":"53"}},{"t":"usc","label":"38 U.S.C. § 4331","url":"https://www.law.cornell.edu/uscode/text/38/4331","subs":["(b)"],"by":{"0":"53"}},{"t":"usc","label":"42 U.S.C. § 1981","url":"https://www.law.cornell.edu/uscode/text/42/1981","subs":["(a)"],"by":{"0":"23"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(m)","(a)(1)"],"stext":{"head":"§2000e–2. Unlawful employment practices","paras":[[0,"(a) Employer practices"],[0,"It shall be an unlawful employment practice for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual, or otherwise to discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(2) to limit, segregate, or classify his employees or applicants for employment in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's race, color, religion, sex, or national origin."],[0,"(b) Employment agency practices"],[0,"It shall be an unlawful employment practice for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin, or to classify or refer for employment any individual on the basis of his race, color, religion, sex, or national origin."],[0,"(c) Labor organization practices"],[0,"It shall be an unlawful employment practice for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin;"],[1,"(2) to limit, segregate, or classify its membership or applicants for membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Training programs"],[0,"It shall be an unlawful employment practice for any employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs to discriminate against any individual because of his race, color, religion, sex, or national origin in admission to, or employment in, any program established to provide apprenticeship or other training."],[0,"(e) Businesses or enterprises with personnel qualified on basis of religion, sex, or national origin; educational institutions with personnel of particular religion"],[0,"Notwithstanding any other provision of this subchapter, (1) it shall not be an unlawful employment practice for an employer to hire and employ employees, for an employment agency to classify, or refer for employment any individual, for a labor organization to classify its membership or to classify or refer for employment any individual, or for an employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining programs to admit or employ any individual in any such program, on the basis of his religion, sex, or national origin in those certain instances where religion, sex, or national origin is a bona fide occupational qualification reasonably necessary to the normal operation of that particular business or enterprise, and (2) it shall not be an unlawful employment practice for a school, college, university, or other educational institution or institution of learning to hire and employ employees of a particular religion if such school, college, university, or other educational institution or institution of learning is, in whole or in substantial part, owned, supported, controlled, or managed by a particular religion or by a particular religious corporation, association, or society, or if the curriculum of such school, college, university, or other educational institution or institution of learning is directed toward the propagation of a particular religion."],[0,"(f) Members of Communist Party or Communist-action or Communist-front organizations"],[0,"As used in this subchapter, the phrase \"unlawful employment practice\" shall not be deemed to include any action or measure taken by an employer, labor organization, joint labor-management committee, or employment agency with respect to an individual who is a member of the Communist Party of the United States or of any other organization required to register as a Communist-action or Communist-front organization by final order of the Subversive Activities Control Board pursuant to the Subversive Activities Control Act of 1950 [50 U.S.C. 781 et seq.]."],[0,"(g) National security"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to fail or refuse to hire and employ any individual for any position, for an employer to discharge any individual from any position, or for an employment agency to fail or refuse to refer any individual for employment in any position, or for a labor organization to fail or refuse to refer any individual for employment in any position, if—"],[1,"(1) the occupancy of such position, or access to the premises in or upon which any part of the duties of such position is performed or is to be performed, is subject to any requirement imposed in the interest of the national security of the United States under any security program in effect pursuant to or administered under any statute of the United States or any Executive order of the President; and"],[1,"(2) such individual has not fulfilled or has ceased to fulfill that requirement."],[0,"(h) Seniority or merit system; quantity or quality of production; ability tests; compensation based on sex and authorized by minimum wage provisions"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to apply different standards of compensation, or different terms, conditions, or privileges of employment pursuant to a bona fide seniority or merit system, or a system which measures earnings by quantity or quality of production or to employees who work in different locations, provided that such differences are not the result of an intention to discriminate because of race, color, religion, sex, or national origin, nor shall it be an unlawful employment practice for an employer to give and to act upon the results of any professionally developed ability test provided that such test, its administration or action upon the results is not designed, intended or used to discriminate because of race, color, religion, sex or national origin. It shall not be an unlawful employment practice under this subchapter for any employer to differentiate upon the basis of sex in determining the amount of the wages or compensation paid or to be paid to employees of such employer if such differentiation is authorized by the provisions of section 206(d) of title 29."],[0,"(i) Businesses or enterprises extending preferential treatment to Indians"],[0,"Nothing contained in this subchapter shall apply to any business or enterprise on or near an Indian reservation with respect to any publicly announced employment practice of such business or enterprise under which a preferential treatment is given to any individual because he is an Indian living on or near a reservation."],[0,"(j) Preferential treatment not to be granted on account of existing number or percentage imbalance"],[0,"Nothing contained in this subchapter shall be interpreted to require any employer, employment agency, labor organization, or joint labor-management committee subject to this subchapter to grant preferential treatment to any individual or to any group because of the race, color, religion, sex, or national origin of such individual or group on account of an imbalance which may exist with respect to the total number or percentage of persons of any race, color, religion, sex, or national origin employed by any employer, referred or classified for employment by any employment agency or labor organization, admitted to membership or classified by any labor organization, or admitted to, or employed in, any apprenticeship or other training program, in comparison with the total number or percentage of persons of such race, color, religion, sex, or national origin in any community, State, section, or other area, or in the available work force in any community, State, section, or other area."],[0,"(k) Burden of proof in disparate impact cases"],[0,"(1)(A) An unlawful employment practice based on disparate impact is established under this subchapter only if—"],[1,"(i) a complaining party demonstrates that a respondent uses a particular employment practice that causes a disparate impact on the basis of race, color, religion, sex, or national origin and the respondent fails to demonstrate that the challenged practice is job related for the position in question and consistent with business necessity; or"],[1,"(ii) the complaining party makes the demonstration described in subparagraph (C) with respect to an alternative employment practice and the respondent refuses to adopt such alternative employment practice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-2?type=usc&year=mostrecent&link-type=html"},"by":{"0":"57","1":"6, 6","2":"20"},"q":[{"src":"brief","b":1,"text":"because of such individual’s race, color, religion, sex, or national origin.","cite":"42 U.S.C. 2000e-2(a)(1)"},{"src":"brief","b":1,"text":"was a motivating factor for any employment practice, even though other factors also motivated the practice.","cite":"42 U.S.C. 2000e-2(m)"}]},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(g)(2)(B)","(g)(2)(B)(ii)"],"by":{"0":"57","1":"6, 42, 6, 42"},"q":[{"src":"brief","b":1,"text":"would have taken the same action in the absence of the impermissible motivating factor.","cite":"42 U.S.C. 2000e-5(g)(2)(B)"}]},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","subs":["(a)"],"stext":{"head":"§2000e–16. Employment by Federal Government","paras":[[0,"(a) Discriminatory practices prohibited; employees or applicants for employment subject to coverage"],[0,"All personnel actions affecting employees or applicants for employment (except with regard to aliens employed outside the limits of the United States) in military departments as defined in section 102 of title 5, in executive agencies as defined in section 105 of title 5 (including employees and applicants for employment who are paid from nonappropriated funds), in the United States Postal Service and the Postal Regulatory Commission, in those units of the Government of the District of Columbia having positions in the competitive service, and in those units of the judicial branch of the Federal Government having positions in the competitive service, in the Smithsonian Institution, and in the Government Publishing Office, the Government Accountability Office, and the Library of Congress shall be made free from any discrimination based on race, color, religion, sex, or national origin."],[0,"(b) Equal Employment Opportunity Commission; enforcement powers; issuance of rules, regulations, etc.; annual review and approval of national and regional equal employment opportunity plans; review and evaluation of equal employment opportunity programs and publication of progress reports; consultations with interested parties; compliance with rules, regulations, etc.; contents of national and regional equal employment opportunity plans; authority of Librarian of Congress"],[0,"Except as otherwise provided in this subsection, the Equal Employment Opportunity Commission shall have authority to enforce the provisions of subsection (a) through appropriate remedies, including reinstatement or hiring of employees with or without back pay, as will effectuate the policies of this section, and shall issue such rules, regulations, orders and instructions as it deems necessary and appropriate to carry out its responsibilities under this section. The Equal Employment Opportunity Commission shall—"],[1,"(1) be responsible for the annual review and approval of a national and regional equal employment opportunity plan which each department and agency and each appropriate unit referred to in subsection (a) of this section shall submit in order to maintain an affirmative program of equal employment opportunity for all such employees and applicants for employment;"],[1,"(2) be responsible for the review and evaluation of the operation of all agency equal employment opportunity programs, periodically obtaining and publishing (on at least a semiannual basis) progress reports from each such department, agency, or unit; and"],[1,"(3) consult with and solicit the recommendations of interested individuals, groups, and organizations relating to equal employment opportunity."],[0,"The head of each such department, agency, or unit shall comply with such rules, regulations, orders, and instructions which shall include a provision that an employee or applicant for employment shall be notified of any final action taken on any complaint of discrimination filed by him thereunder. The plan submitted by each department, agency, and unit shall include, but not be limited to—"],[1,"(1) provision for the establishment of training and education programs designed to provide a maximum opportunity for employees to advance so as to perform at their highest potential; and"],[1,"(2) a description of the qualifications in terms of training and experience relating to equal employment opportunity for the principal and operating officials of each such department, agency, or unit responsible for carrying out the equal employment opportunity program and of the allocation of personnel and resources proposed by such department, agency, or unit to carry out its equal employment opportunity program."],[0,"With respect to employment in the Library of Congress, authorities granted in this subsection to the Equal Employment Opportunity Commission shall be exercised by the Librarian of Congress."],[0,"(c) Civil action by employee or applicant for employment for redress of grievances; time for bringing of action; head of department, agency, or unit as defendant"],[0,"Within 90 days of receipt of notice of final action taken by a department, agency, or unit referred to in subsection (a), or by the Equal Employment Opportunity Commission upon an appeal from a decision or order of such department, agency, or unit on a complaint of discrimination based on race, color, religion, sex or national origin, brought pursuant to subsection (a) of this section, Executive Order 11478 or any succeeding Executive orders, or after one hundred and eighty days from the filing of the initial charge with the department, agency, or unit or with the Equal Employment Opportunity Commission on appeal from a decision or order of such department, agency, or unit until such time as final action may be taken by a department, agency, or unit, an employee or applicant for employment, if aggrieved by the final disposition of his complaint, or by the failure to take final action on his complaint, may file a civil action as provided in section 2000e–5 of this title, in which civil action the head of the department, agency, or unit, as appropriate, shall be the defendant."],[0,"(d) Section 2000e–5(f) through (k) of this title applicable to civil actions"],[0,"The provisions of section 2000e–5(f) through (k) of this title, as applicable, shall govern civil actions brought hereunder, and the same interest to compensate for delay in payment shall be available as in cases involving nonpublic parties..1"],[0,"(e) Government agency or official not relieved of responsibility to assure nondiscrimination in employment or equal employment opportunity"],[0,"Nothing contained in this Act shall relieve any Government agency or official of its or his primary responsibility to assure nondiscrimination in employment as required by the Constitution and statutes or of its or his responsibilities under Executive Order 11478 relating to equal employment opportunity in the Federal Government."],[0,"(f) Section 2000e–5(e)(3) of this title applicable to compensation discrimination"],[0,"Section 2000e–5(e)(3) of this title shall apply to complaints of discrimination in compensation under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-16?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4, 8, 29","1":"6, 42, 3","2":"1"},"q":[{"src":"brief","b":0,"text":"shall be made free from any discrimination based on race, color, religion, sex, or national origin.","cite":"42 U.S.C. § 2000e-16(a)"},{"src":"brief","b":1,"text":"shall be made free from any discrimination based on race, color, religion, sex, or national origin.","cite":"42 U.S.C. 2000e-16(a)"}]},{"t":"usc","label":"42 U.S.C. § 2000e-16b","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16b","by":{"0":"52"}},{"t":"usc","label":"42 U.S.C. § 9604","url":"https://www.law.cornell.edu/uscode/text/42/9604","subs":["(e)(7)(C)"],"by":{"0":"22","1":"29"}},{"t":"usc","label":"43 U.S.C. § 618c","url":"https://www.law.cornell.edu/uscode/text/43/618c","subs":["(a)"],"by":{"0":"23","1":"30"}},{"t":"law","label":"Pub. L. No. 88-352","url":"https://www.govinfo.gov/link/statute/78/241","by":{"0":"6, 7"}},{"t":"law","label":"Pub. L. No. 90-202","url":"https://www.govinfo.gov/link/statute/81/602","by":{"0":"7"}},{"t":"law","label":"Pub. L. No. 92-261","url":"https://www.govinfo.gov/link/statute/86/103","by":{"0":"8, 9, 36","1":"6, 41"}},{"t":"law","label":"Pub. L. No. 93-259","url":"https://www.govinfo.gov/link/statute/88/55","by":{"0":"9, 38","1":"6"}},{"t":"reg","label":"5 C.F.R. § 713.271","url":"https://www.ecfr.gov/current/title-5/section-713.271","subs":["(a)","(a)(1)","(a)(2)","(b)(1)","(b)(2)"],"by":{"0":"37, 37, 9, 37, 9, 37, 9, 37, 9, 37","2":"13, 14, 13"}},{"t":"reg","label":"5 C.F.R. § 713.511","url":"https://www.ecfr.gov/current/title-5/section-713.511","by":{"0":"10, 39"}},{"t":"reg","label":"29 C.F.R. pt. 1613","url":"https://www.ecfr.gov/current/title-29/part-1613","by":{"0":"39"}},{"t":"reg","label":"29 C.F.R. pt. 1614","url":"https://www.ecfr.gov/current/title-29/part-1614","by":{"0":"10, 5"}},{"t":"reg","label":"29 C.F.R. § 1614.501","url":"https://www.ecfr.gov/current/title-29/section-1614.501","subs":["(a)(3)","(b)(1)","(b)(2)","(c)(1)","(c)(2)"],"by":{"0":"10, 39, 47, 47, 40, 40, 40, 40, 41"},"q":[{"src":"brief","b":0,"text":"nevertheless take all steps necessary to eliminate the discriminatory practice and ensure it does not recur.","cite":"29 C.F.R. § 1614.501(b)(2)"},{"src":"brief","b":0,"text":"the personnel action would have been taken even absent discrimination.","cite":"29 C.F.R. § 1614.501(c)(2)"}]},{"t":"reg","label":"3 C.F.R. pt. 824","url":"https://www.ecfr.gov/current/title-3/part-824","by":{"0":"34","1":"38"}},{"t":"reg","label":"3 C.F.R. pt. 234","url":"https://www.ecfr.gov/current/title-3/part-234","by":{"0":"6, 34"},"q":[{"src":"brief","b":0,"text":"because of race, creed, color, or national origin.","cite":"3 C.F.R. 234"}]},{"t":"reg","label":"3 C.F.R. pt. 1280","url":"https://www.ecfr.gov/current/title-3/part-1280","by":{"0":"34","1":"38, 39"}},{"t":"reg","label":"3 C.F.R. pt. 720","url":"https://www.ecfr.gov/current/title-3/part-720","by":{"0":"34, 35","1":"40"},"q":[{"src":"brief","b":0,"text":"[a]ll personnel actions taken by Federal appointing officers shall be based solely on merit and fitness.","cite":"3 C.F.R. 720"}]},{"t":"reg","label":"3 C.F.R. pt. 53","url":"https://www.ecfr.gov/current/title-3/part-53","by":{"0":"34"}},{"t":"reg","label":"3 C.F.R. pt. 86","url":"https://www.ecfr.gov/current/title-3/part-86","by":{"0":"34"}},{"t":"reg","label":"3 C.F.R. pt. 117","url":"https://www.ecfr.gov/current/title-3/part-117","by":{"0":"6, 35"},"q":[{"src":"brief","b":0,"text":"fair and full consideration for employment and advancement in Federal employment.","cite":"3 C.F.R. 117"}]},{"t":"reg","label":"3 C.F.R. pt. 167","url":"https://www.ecfr.gov/current/title-3/part-167","by":{"0":"34"}},{"t":"reg","label":"3 C.F.R. pt. 133","url":"https://www.ecfr.gov/current/title-3/part-133","by":{"0":"34"}},{"t":"reg","label":"37 Fed. Reg. 22,717","url":"https://www.govinfo.gov/link/fr/37/22717","by":{"0":"9, 37","1":"42","2":"13"}},{"t":"reg","label":"39 Fed. Reg. 24,351","url":"https://www.govinfo.gov/link/fr/39/24351","by":{"0":"10, 38"}},{"t":"reg","label":"43 Fed. Reg. 60,900","url":"https://www.govinfo.gov/link/fr/43/60900","by":{"0":"10, 39","1":"44"}},{"t":"reg","label":"54 Fed. Reg. 45,747","url":"https://www.govinfo.gov/link/fr/54/45747","by":{"0":"39"}},{"t":"reg","label":"57 Fed. Reg. 12,634","url":"https://www.govinfo.gov/link/fr/57/12634","by":{"0":"39","1":"46, 47"}},{"t":"reg","label":"Reorganization Plan No. 1 of 1978, § 2, 43 Fed. Reg. 19,807,","url":"https://www.govinfo.gov/link/fr/43/19807","by":{"0":"10, 39"}},{"t":"case","label":"Ayon v. Sampson","cite":"547 F.2d 446","y":1976,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/547/446/","by":{"1":"6"}},{"t":"case","label":"Boehms v. Crowell","cite":"139 F.3d 452","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/139/452/","by":{"1":"37"}},{"t":"case","label":"Burrage v. United States","cite":"571 U.S. 204","y":2014,"id":"2013/12-7515","sc":1,"by":{"1":"4, 22"}},{"t":"case","label":"Freeman v. Quicken Loans, Inc.","cite":"566 U.S. 624","y":2012,"id":"2011/10-1042","sc":1,"by":{"1":"29"}},{"t":"case","label":"General Dynamics Land Sys., Inc. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"by":{"1":"45"}},{"t":"case","label":"Green v. Brennan","cite":"136 S. Ct. 1769","y":2016,"id":"2015/14-613","sc":1,"by":{"1":"6"}},{"t":"case","label":"Hale v. Marsh","cite":"808 F.2d 616","y":1986,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/808/616/","by":{"1":"6"}},{"t":"case","label":"Hazen Paper Co. v. Biggins","cite":"507 U.S. 604","y":1993,"id":"1992/91-1600","sc":1,"by":{"1":"19"}},{"t":"case","label":"Nita H. v. Jewell, Pet. No. 0320110050","cite":"2014 WL 3788011","y":2014,"court":"E.E.O.C. July 16","by":{"1":"49, 50"}},{"t":"case","label":"Nowd v. Rubin","cite":"76 F.3d 25","y":1996,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/76/25/","by":{"1":"37"}},{"t":"case","label":"Safeco Ins. Co. of Am. v. Burr","cite":"551 U.S. 47","y":2007,"id":"2006/06-84","sc":1,"by":{"1":"12, 16, 19, 20, 30, 31","2":"15"},"q":[{"src":"brief","b":1,"text":"[T]he phrase ‘based on’ indicates a but-for causal relationship.","cite":"551 U.S. 47, 63"},{"src":"brief","b":1,"text":"indicates a butfor causal relationship and thus a necessary logical condition.","cite":"551 U.S. at 63"}]},{"t":"case","label":"Skidmore v. Swift & Co.","cite":"323 U.S. 134","y":1944,"id":"1940-1955/12","sc":1,"by":{"1":"45"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"by":{"1":"40"},"q":[{"src":"brief","b":1,"text":"‘prohibited personnel practices,’ including unlawful discrimination, coercion of political activity, nepotism, and reprisal against socalled whistleblowers.","cite":"484 U.S. 439, 446"}]},{"t":"const","label":"Amendment XIV","clauses":[["equal-protection","Equal Protection Clause"]],"by":{"1":"27, 35"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","by":{"1":"2"}},{"t":"usc","label":"29 U.S.C. § 626","url":"https://www.law.cornell.edu/uscode/text/29/626","subs":["(b)"],"by":{"1":"37"}},{"t":"usc","label":"29 U.S.C. § 630","url":"https://www.law.cornell.edu/uscode/text/29/630","subs":["(b)"],"by":{"1":"passim"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","subs":["(b)"],"by":{"1":"passim, 6"},"q":[{"src":"brief","b":1,"text":"because of such individual’s race, color, religion, sex, or national origin.","cite":"42 U.S.C. 2000e"},{"src":"brief","b":1,"text":"was a motivating factor for any employment practice, even though other factors also motivated the practice.","cite":"42 U.S.C. 2000e"}]},{"t":"usc","label":"42 U.S.C. § 2000e-3","url":"https://www.law.cornell.edu/uscode/text/42/2000e-3","subs":["(a)"],"stext":{"head":"§2000e–3. Other unlawful employment practices","paras":[[0,"(a) Discrimination for making charges, testifying, assisting, or participating in enforcement proceedings"],[0,"It shall be an unlawful employment practice for an employer to discriminate against any of his employees or applicants for employment, for an employment agency, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs, to discriminate against any individual, or for a labor organization to discriminate against any member thereof or applicant for membership, because he has opposed any practice made an unlawful employment practice by this subchapter, or because he has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or hearing under this subchapter."],[0,"(b) Printing or publication of notices or advertisements indicating prohibited preference, limitation, specification, or discrimination; occupational qualification exception"],[0,"It shall be an unlawful employment practice for an employer, labor organization, employment agency, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs, to print or publish or cause to be printed or published any notice or advertisement relating to employment by such an employer or membership in or any classification or referral for employment by such a labor organization, or relating to any classification or referral for employment by such an employment agency, or relating to admission to, or employment in, any program established to provide apprenticeship or other training by such a joint labor-management committee, indicating any preference, limitation, specification, or discrimination, based on race, color, religion, sex, or national origin, except that such a notice or advertisement may indicate a preference, limitation, specification, or discrimination based on religion, sex, or national origin when religion, sex, or national origin is a bona fide occupational qualification for employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-3?type=usc&year=mostrecent&link-type=html"},"by":{"1":"6, 6, 42","2":"19"},"q":[{"src":"brief","b":1,"text":"unlawful employment practice for an employer to discriminate against any of his employees or applicants for employment * * * because he has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or hearing under [Title VII].","cite":"42 U.S.C. 2000e-3(a)"},{"src":"brief","b":2,"text":"for an employer to discriminate against any of [its] employees . . . because [the employee] has opposed","cite":"42 U.S.C. § 2000e-3(a)"}]},{"t":"usc","label":"5 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/5/1101","by":{"1":"32"}},{"t":"usc","label":"5 U.S.C. § 2301","url":"https://www.law.cornell.edu/uscode/text/5/2301","subs":["(b)","(b)(2)"],"by":{"1":"40, 32"},"q":[{"src":"argument","who":"Mr. Martinez","text":"His deus ex machina here is Section 2301 of the CSRA. That's a cruel joke that will be played on -- on this Court if you accept that rationale."}]},{"t":"usc","label":"5 U.S.C. § 2302","url":"https://www.law.cornell.edu/uscode/text/5/2302","subs":["(1982)","(a)(2)(A)"],"by":{"1":"40, 34"},"q":[{"src":"argument","who":"Mr. Martinez","text":"Well, under the civil service laws, Your Honor, the -- the way the civil service laws work is Section 2302 of the CSRA says that the way you bring a discrimination claim is to sue under this statute that we're currently talking about."}]},{"t":"usc","label":"28 U.S.C. § 2412","url":"https://www.law.cornell.edu/uscode/text/28/2412","subs":["(b)"],"by":{"1":"37"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","by":{"1":"19"}},{"t":"usc","label":"15 U.S.C. § 1681m","url":"https://www.law.cornell.edu/uscode/text/15/1681m","subs":["(a)(2000)","(a)"],"stext":{"head":"§1681m. Requirements on users of consumer reports","paras":[[0,"(a) Duties of users taking adverse actions on basis of information contained in consumer reports"],[0,"If any person takes any adverse action with respect to any consumer that is based in whole or in part on any information contained in a consumer report, the person shall—"],[1,"(1) provide oral, written, or electronic notice of the adverse action to the consumer;"],[1,"(2) provide to the consumer written or electronic disclosure—"],[2,"(A) of a numerical credit score as defined in section 1681g(f)(2)(A) of this title used by such person in taking any adverse action based in whole or in part on any information in a consumer report; and"],[2,"(B) of the information set forth in subparagraphs (B) through (E) of section 1681g(f)(1) of this title;"],[1,"(3) provide to the consumer orally, in writing, or electronically—"],[2,"(A) the name, address, and telephone number of the consumer reporting agency (including a toll-free telephone number established by the agency if the agency compiles and maintains files on consumers on a nationwide basis) that furnished the report to the person; and"],[2,"(B) a statement that the consumer reporting agency did not make the decision to take the adverse action and is unable to provide the consumer the specific reasons why the adverse action was taken; and"],[1,"(4) provide to the consumer an oral, written, or electronic notice of the consumer's right—"],[2,"(A) to obtain, under section 1681j of this title, a free copy of a consumer report on the consumer from the consumer reporting agency referred to in paragraph (3), which notice shall include an indication of the 60-day period under that section for obtaining such a copy; and"],[2,"(B) to dispute, under section 1681i of this title, with a consumer reporting agency the accuracy or completeness of any information in a consumer report furnished by the agency."],[0,"(b) Adverse action based on information obtained from third parties other than consumer reporting agencies"],[0,"(1) In general"],[1,"Whenever credit for personal, family, or household purposes involving a consumer is denied or the charge for such credit is increased either wholly or partly because of information obtained from a person other than a consumer reporting agency bearing upon the consumer's credit worthiness, credit standing, credit capacity, character, general reputation, personal characteristics, or mode of living, the user of such information shall, within a reasonable period of time, upon the consumer's written request for the reasons for such adverse action received within sixty days after learning of such adverse action, disclose the nature of the information to the consumer. The user of such information shall clearly and accurately disclose to the consumer his right to make such written request at the time such adverse action is communicated to the consumer."],[0,"(2) Duties of person taking certain actions based on information provided by affiliate"],[0,"(A) Duties, generally"],[2,"If a person takes an action described in subparagraph (B) with respect to a consumer, based in whole or in part on information described in subparagraph (C), the person shall—"],[3,"(i) notify the consumer of the action, including a statement that the consumer may obtain the information in accordance with clause (ii); and"],[3,"(ii) upon a written request from the consumer received within 60 days after transmittal of the notice required by clause (i), disclose to the consumer the nature of the information upon which the action is based by not later than 30 days after receipt of the request."],[0,"(B) Action described"],[2,"An action referred to in subparagraph (A) is an adverse action described in section 1681a(k)(1)(A) of this title, taken in connection with a transaction initiated by the consumer, or any adverse action described in clause (i) or (ii) of section 1681a(k)(1)(B) of this title."],[0,"(C) Information described"],[2,"Information referred to in subparagraph (A)—"],[3,"(i) except as provided in clause (ii), is information that—"],[4,"(I) is furnished to the person taking the action by a person related by common ownership or affiliated by common corporate control to the person taking the action; and"],[4,"(II) bears on the credit worthiness, credit standing, credit capacity, character, general reputation, personal characteristics, or mode of living of the consumer; and"],[3,"(ii) does not include—"],[4,"(I) information solely as to transactions or experiences between the consumer and the person furnishing the information; or"],[4,"(II) information in a consumer report."],[0,"(c) Reasonable procedures to assure compliance"],[0,"No person shall be held liable for any violation of this section if he shows by a preponderance of the evidence that at the time of the alleged violation he maintained reasonable procedures to assure compliance with the provisions of this section."],[0,"(d) Duties of users making written credit or insurance solicitations on basis of information contained in consumer files"],[0,"(1) In general"],[1,"Any person who uses a consumer report on any consumer in connection with any credit or insurance transaction that is not initiated by the consumer, that is provided to that person under section 1681b(c)(1)(B) of this title, shall provide with each written solicitation made to the consumer regarding the transaction a clear and conspicuous statement that—"],[2,"(A) information contained in the consumer's consumer report was used in connection with the transaction;"],[2,"(B) the consumer received the offer of credit or insurance because the consumer satisfied the criteria for credit worthiness or insurability under which the consumer was selected for the offer;"],[2,"(C) if applicable, the credit or insurance may not be extended if, after the consumer responds to the offer, the consumer does not meet the criteria used to select the consumer for the offer or any applicable criteria bearing on credit worthiness or insurability or does not furnish any required collateral;"],[2,"(D) the consumer has a right to prohibit information contained in the consumer's file with any consumer reporting agency from being used in connection with any credit or insurance transaction that is not initiated by the consumer; and"],[2,"(E) the consumer may exercise the right referred to in subparagraph (D) by notifying a notification system established under section 1681b(e) of this title."],[0,"(2) Disclosure of address and telephone number; format"],[1,"A statement under paragraph (1) shall—"],[2,"(A) include the address and toll-free telephone number of the appropriate notification system established under section 1681b(e) of this title; and"],[2,"(B) be presented in such format and in such type size and manner as to be simple and easy to understand, as established by the Bureau, by rule, in consultation with the Federal Trade Commission, the Federal banking agencies, and the National Credit Union Administration."],[0,"(3) Maintaining criteria on file"],[1,"A person who makes an offer of credit or insurance to a consumer under a credit or insurance transaction described in paragraph (1) shall maintain on file the criteria used to select the consumer to receive the offer, all criteria bearing on credit worthiness or insurability, as applicable, that are the basis for determining whether or not to extend credit or insurance pursuant to the offer, and any requirement for the furnishing of collateral as a condition of the extension of credit or insurance, until the expiration of the 3-year period beginning on the date on which the offer is made to the consumer."],[0,"(4) Authority of Federal agencies regarding unfair or deceptive acts or practices not affected"],[1,"This section is not intended to affect the authority of any Federal or State agency to enforce a prohibition against unfair or deceptive acts or practices, including the making of false or misleading statements in connection with a credit or insurance transaction that is not initiated by the consumer."],[0,"(e) Red flag guidelines and regulations required"],[0,"(1) Guidelines"],[1,"The Federal banking agencies, the National Credit Union Administration, the Federal Trade Commission, the Commodity Futures Trading Commission, and the Securities and Exchange Commission shall jointly, with respect to the entities that are subject to their respective enforcement authority under section 1681s of this title—"],[2,"(A) establish and maintain guidelines for use by each financial institution and each creditor regarding identity theft with respect to account holders at, or customers of, such entities, and update such guidelines as often as necessary;"],[2,"(B) prescribe regulations requiring each financial institution and each creditor to establish reasonable policies and procedures for implementing the guidelines established pursuant to subparagraph (A), to identify possible risks to account holders or customers or to the safety and soundness of the institution or customers; and"],[2,"(C) prescribe regulations applicable to card issuers to ensure that, if a card issuer receives notification of a change of address for an existing account, and within a short period of time (during at least the first 30 days after such notification is received) receives a request for an additional or replacement card for the same account, the card issuer may not issue the additional or replacement card, unless the card issuer, in accordance with reasonable policies and procedures—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681m?type=usc&year=mostrecent&link-type=html"},"by":{"1":"19, 30","2":"18"},"q":[{"src":"brief","b":1,"text":"any person [who] takes any adverse action with respect to any consumer that is based in whole or in part on any information contained in a consumer report","cite":"15 U.S.C. 1681m(a)"},{"src":"brief","b":2,"text":"any person [who] takes any adverse action with respect to any consumer that is based in whole or in part on any information contained in a consumer report","cite":"15 U.S.C. § 1681m(a)"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"[i]f any person takes any adverse action with respect to any consumer that is based in whole or in part on any information contained in a consumer [credit] report.","cite":"15 U. S. C. § 1681m(a)"}]},{"t":"reg","label":"3 C.F.R. pt. 957","url":"https://www.ecfr.gov/current/title-3/part-957","by":{"1":"38, 39"}},{"t":"reg","label":"3 C.F.R. pt. 721","url":"https://www.ecfr.gov/current/title-3/part-721","by":{"1":"38"}},{"t":"reg","label":"3 C.F.R. pt. 237","url":"https://www.ecfr.gov/current/title-3/part-237","by":{"1":"38"}},{"t":"reg","label":"3 C.F.R. pt. 449","url":"https://www.ecfr.gov/current/title-3/part-449","by":{"1":"38"}},{"t":"reg","label":"3 C.F.R. pt. 180","url":"https://www.ecfr.gov/current/title-3/part-180","by":{"1":"38, 40"}},{"t":"reg","label":"3 C.F.R. pt. 339","url":"https://www.ecfr.gov/current/title-3/part-339","by":{"1":"38"}},{"t":"reg","label":"3 C.F.R. pt. 685","url":"https://www.ecfr.gov/current/title-3/part-685","by":{"1":"38"}},{"t":"reg","label":"3 C.F.R. pt. 804","url":"https://www.ecfr.gov/current/title-3/part-804","by":{"1":"38"}},{"t":"reg","label":"3 C.F.R. pt. 235","url":"https://www.ecfr.gov/current/title-3/part-235","by":{"1":"40, 41"}},{"t":"reg","label":"3 C.F.R. pt. 264","url":"https://www.ecfr.gov/current/title-3/part-264","by":{"1":"41"}},{"t":"reg","label":"51 Fed. Reg. 29,482","url":"https://www.govinfo.gov/link/fr/51/29482","by":{"1":"47"}},{"t":"reg","label":"52 Fed. Reg. 41,920","url":"https://www.govinfo.gov/link/fr/52/41920","by":{"1":"47"}},{"t":"case","label":"Fitzgerald v. Barnstable School Committee","cite":"555 U.S. 246","y":2009,"id":"2008/07-1125","sc":1,"by":{"2":"9, 10"}},{"t":"case","label":"Geraldine G. v. Brennan, Appeal No. 0720140039","cite":"2016 WL 3361226","y":2016,"court":"E.E.O.C. June 3","by":{"2":"24"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"by":{"2":"16"}},{"t":"case","label":"Maxfield v. Sinclair International","cite":"766 F.2d 788","y":1985,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/766/788/","by":{"2":"23"}},{"t":"case","label":"Miller v. Johnson","cite":"515 U.S. 900","y":1995,"id":"1994/94-631","sc":1,"by":{"2":"7"}},{"t":"case","label":"Rice v. Cayetano","cite":"528 U.S. 495","y":2000,"id":"1999/98-818","sc":1,"by":{"2":"7"}},{"t":"case","label":"Texas Department of Community Affairs v. Burdine","cite":"450 U.S. 248","y":1981,"id":"1980/79-1764","sc":1,"by":{"2":"22"}},{"t":"case","label":"Thigpen v. Bibb County","cite":"223 F.3d 1231","y":2000,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/223/1231/","by":{"2":"10"}},{"t":"case","label":"United States v. Raines","cite":"189 F. Supp. 121","y":1960,"court":"M.D. Ga.","url":"https://www.courtlistener.com/c/F.%20Supp./189/121/","by":{"2":"5"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"by":{"2":"17"}},{"t":"usc","label":"42 U.S.C. § 2000d","url":"https://www.law.cornell.edu/uscode/text/42/2000d","by":{"2":"9"}}]};